<?php require __DIR__.'/../config.php';require_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$cat=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$stock=max(0,(int)($_POST['stock']??0));$desc=trim($_POST['description']??'');if($name&&$cat&&$price>=0){if($id){$s=$pdo->prepare('UPDATE medicines SET name=?,category_id=?,price=?,stock=?,description=? WHERE id=?');$s->execute([$name,$cat,$price,$stock,$desc,$id]);}else{$s=$pdo->prepare('INSERT INTO medicines(name,category_id,price,stock,description) VALUES(?,?,?,?,?)');$s->execute([$name,$cat,$price,$stock,$desc]);}flash('Medicine saved.');go('/MediHome/admin/medicines.php');}else $msg='Fill the required fields.';}if($action==='delete'){$id=(int)$_POST['id'];$s=$pdo->prepare('SELECT COUNT(*) FROM order_items WHERE medicine_id=?');$s->execute([$id]);if($s->fetchColumn())flash('Cannot delete a medicine already present in order history.','error');else{$s=$pdo->prepare('DELETE FROM medicines WHERE id=?');$s->execute([$id]);flash('Medicine deleted.');}go('/MediHome/admin/medicines.php');}}$cats=$pdo->query('SELECT * FROM categories')->fetchAll();$meds=$pdo->query('SELECT m.*,c.name category_name FROM medicines m JOIN categories c ON c.id=m.category_id ORDER BY m.id DESC')->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM medicines WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$title='Manage Medicines | MediHome';require __DIR__.'/../includes/header.php';?><div class="pagehead"><h1>Manage medicines</h1><p>Add, edit or remove catalog products.</p></div><div class="adminnav"><a href="/MediHome/admin/index.php">Dashboard</a><a href="/MediHome/admin/medicines.php">Medicines</a><a href="/MediHome/admin/orders.php">Orders</a><a href="/MediHome/admin/logout.php">Logout</a></div><div class="formbox" style="max-width:none"><h2><?= $edit?'Edit medicine':'Add medicine'?></h2><?php if($msg):?><div class="flash error"><?=e($msg)?></div><?php endif;?><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="field"><label>Name</label><input class="input" name="name" required value="<?=e($edit['name']??'')?>"></div><div class="field"><label>Category</label><select name="category_id"><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>" <?=(int)($edit['category_id']??0)===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Price</label><input class="input" type="number" min="0" step=".01" name="price" required value="<?=e((string)($edit['price']??''))?>"></div><div class="field"><label>Stock</label><input class="input" type="number" min="0" name="stock" value="<?=e((string)($edit['stock']??0))?>"></div><div class="field"><label>Description</label><textarea name="description"><?=e($edit['description']??'')?></textarea></div><button class="btn">Save medicine</button></form></div><div class="tablewrap section"><table class="table"><tr><th>Name</th><th>Category</th><th>Price</th><th>Stock</th><th>Actions</th></tr><?php foreach($meds as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['category_name'])?></td><td><?=money($m['price'])?></td><td><?=(int)$m['stock']?></td><td><a class="btn ghost" href="?edit=<?=(int)$m['id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Delete this item?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$m['id']?>"><button class="btn" style="background:#b43b34">Delete</button></form></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../includes/footer.php';?>